class Provider {
    constructor() {
        this.baseUrl = "https://mangafire.to";
        this.apiUrl = this.baseUrl + "/api";
    }

    getSettings() {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: true
        };
    }

    async request(url) {
        const response = await fetch(url, {
            headers: {
                "Accept": "application/json",
                "Referer": this.baseUrl + "/"
            }
        });

        if (!response.ok) {
            throw new Error("MangaFire request failed: HTTP " + response.status);
        }

        return await response.json();
    }

    async search(opts) {
        const query = encodeURIComponent(opts.query);
        const url = this.apiUrl +
            "/titles?keyword=" + query +
            "&language=en&limit=30&page=1";

        const json = await this.request(url);

        if (!json || !Array.isArray(json.items)) {
            return [];
        }

        return json.items.map(item => ({
            id: String(item.id),
            title: item.title || "",
            synonyms: [],
            image: item.poster && item.poster.medium
                ? item.poster.medium
                : undefined
        }));
    }

    async findChapters(id) {
        const chapters = [];
        let page = 1;

        while (page <= 100) {
            const url = this.apiUrl +
                "/titles/" + encodeURIComponent(id) +
                "/chapters?language=en&sort=number&order=desc&limit=200&page=" +
                page;

            const json = await this.request(url);

            if (!json || !Array.isArray(json.items)) {
                break;
            }

            for (const item of json.items) {
                const chapterId = String(item.id);
                const number = item.number != null ? String(item.number) : "";

                chapters.push({
                    id: chapterId,
                    url: this.baseUrl + "/chapter/" + chapterId,
                    title: item.name
                        ? "Ch. " + number + ": " + item.name
                        : "Ch. " + number,
                    chapter: number,
                    index: chapters.length,
                    scanlator: item.type === "official" ? "official" : undefined,
                    language: item.language || "en",
                    updatedAt: item.createdAt
                        ? new Date(item.createdAt * 1000).toISOString()
                        : undefined
                });
            }

            if (!(json.meta && json.meta.hasNext === true)) {
                break;
            }

            page++;
        }

        return chapters;
    }

    async findChapterPages(id) {
        const url = this.apiUrl + "/chapters/" + encodeURIComponent(id);
        const json = await this.request(url);

        if (!json || !json.data || !Array.isArray(json.data.pages)) {
            return [];
        }

        return json.data.pages.map((page, index) => ({
            url: page.url,
            index: index,
            headers: {
                "Referer": this.baseUrl + "/"
            }
        }));
    }
}
